import java.util.Scanner;

public class Main {
    static int totalN, totalK, modVal;
    static long[] factArr = new long[250004];
    static long[] invFactArr = new long[250004];
    static long[][] memoTable = new long[27][250004];

    static int getBit(int x) {
        return x & (-x);
    }

    static long modPow(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % modVal;
            base = (base * base) % modVal;
            exp >>= 1;
        }
        return res;
    }

    static void precomputeValues() {
        factArr[0] = 1;
        for (int i = 1; i <= totalN; ++i)
            factArr[i] = (factArr[i - 1] * i) % modVal;
        invFactArr[totalN] = modPow(factArr[totalN], modVal - 2);
        for (int i = totalN - 1; i >= 0; --i)
            invFactArr[i] = (invFactArr[i + 1] * (i + 1)) % modVal;
    }

    static long recursiveDP(int x, int s) {
        if (memoTable[x][s] != -1) return memoTable[x][s];
        if (s == 0) return memoTable[x][s] = ((factArr[totalN] * factArr[totalK]) % modVal) * invFactArr[totalK - x] % modVal;
        int remaining = s - getBit(s);
        long sumRes = 0;
        for (int t = remaining; t != 0; t = (t - 1) & remaining)
            sumRes = (sumRes + recursiveDP(x + 1, t) * invFactArr[s - t]) % modVal;
        sumRes = (sumRes + recursiveDP(x + 1, 0) * invFactArr[s]) % modVal;
        return memoTable[x][s] = sumRes;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalN = sc.nextInt();
        totalK = sc.nextInt();
        modVal = sc.nextInt();
        precomputeValues();
        long ans = modPow(totalK, totalN);
        if (totalN % 2 == 0) {
            for (int i = 0; i < 27; i++) {
                for (int j = 0; j <= totalN; j++) {
                    memoTable[i][j] = -1;
                }
            }
            ans = (ans - recursiveDP(0, totalN) + modVal) % modVal;
        }
        System.out.println(ans);
        sc.close();
    }
}
